 * Group the changes from both sides into regions and resolve each one.
 */
export function buildRegions(base, mine, theirs, changesMine, changesTheirs) {
  const baseLen = base.length
  const all = [...changesMine, ...changesTheirs].sort((a, b) => {
    if (a.baseStart !== b.baseStart) return a.baseStart - b.baseStart
    if (a.side === b.side) return 0
    return a.side === 'mine' ? -1 : 1
  })

  const groups = []
  for (const change of all) {
    const last = groups[groups.length - 1]
    if (last && change.baseStart <= last.end) {
      last.end = Math.max(last.end, change.baseEnd)
      last.changes.push(change)
    } else {
      groups.push({ start: change.baseStart, end: change.baseEnd, changes: [change] })
    }
  }

  const regions = []
  let pos = 0
  for (const group of groups) {
    if (group.start > pos) regions.push({ type: 'stable', start: pos, end: group.start })
    regions.push({ type: 'change', start: group.start, end: group.end, changes: group.changes })
    pos = group.end
  }
  if (pos < baseLen) regions.push({ type: 'stable', start: pos, end: baseLen })

  return regions.map(region => resolveRegion(region, base, mine, theirs))
}

function resolveRegion(region, base, mine, theirs) {
  const baseLines = base.slice(region.start, region.end)

  if (region.type === 'stable') {
    return { kind: 'stable', lines: baseLines }
  }

  const mineChanges = region.changes.filter(c => c.side === 'mine')
  const theirsChanges = region.changes.filter(c => c.side === 'theirs')
  const mineLines = sideLines(region, mine, mineChanges, base)
  const theirsLines = sideLines(region, theirs, theirsChanges, base)

  if (arraysEqual(mineLines, theirsLines)) {
    if (mineChanges.length > 0 && theirsChanges.length > 0) return { kind: 'both', lines: mineLines }
    return { kind: mineChanges.length > 0 ? 'mine' : 'theirs', lines: mineLines }
  }
  if (arraysEqual(mineLines, baseLines)) {
    return { kind: 'theirs', lines: theirsLines }
  }
  if (arraysEqual(theirsLines, baseLines)) {
    return { kind: 'mine', lines: mineLines }
  }
  return { kind: 'conflict', mineLines, baseLines, theirsLines }
}

function sideLines(region, doc, ownChanges, base) {
  if (ownChanges.length === 0) return base.slice(region.start, region.end)

  const ownStart = Math.min(...ownChanges.map(c => c.baseStart))
  const ownEnd = Math.max(...ownChanges.map(c => c.baseEnd))
  const startChange = ownChanges.find(c => c.baseStart === ownStart)
  const endChange = ownChanges.find(c => c.baseEnd === ownEnd)
  const sideStart = startChange.sideStart - (ownStart - region.start)
  const sideEnd = endChange.sideEnd + (region.end - ownEnd)
  return doc.slice(sideStart, sideEnd)
}

function arraysEqual(a, b) {
  return a.length === b.length && a.every((value, index) => value === b[index])
}
"}

