 * Render resolved regions as `merge`/`merge2` text or as `regions` text.
 */
export function formatMerge(resolutions, { includeBase }) {
  const lines = []
  let conflict = false
  for (const r of resolutions) {
    if (r.kind === 'conflict') {
      conflict = true
      lines.push('<<<<<<< mine', ...r.mineLines)
      if (includeBase) lines.push('||||||| base', ...r.baseLines)
      lines.push('=======', ...r.theirsLines, '>>>>>>> theirs')
    } else {
      lines.push(...r.lines)
    }
  }
  return { text: toText(lines), conflict }
}

export function formatRegions(resolutions) {
  const lines = []
  let conflict = false
  for (const r of resolutions) {
    if (r.kind === 'conflict') {
      conflict = true
      lines.push(`conflict mine=${r.mineLines.length} base=${r.baseLines.length} theirs=${r.theirsLines.length}`)
    } else {
      lines.push(`${r.kind} ${r.lines.length}`)
    }
  }
  return { text: toText(lines), conflict }
}

function toText(lines) {
  return lines.length ? lines.join('\n') + '\n' : ''
}
"}

