/**
 * The command. `node src/cli.js merge`, `node src/cli.js merge2` and
 * `node src/cli.js regions` each read three documents from standard input and
 * report the three-way merge of the second into the first and the third.
 */
import { splitInput } from './parse.js'
import { computeChanges } from './lcs.js'
import { buildRegions } from './regions.js'
import { formatMerge, formatRegions } from './format.js'

const MODES = ['merge', 'merge2', 'regions']

function fail(message) {
  process.stderr.write(`error: ${message}\n`)
  process.exitCode = 2
}

function readStdin() {
  return new Promise((resolve, reject) => {
    const chunks = []
    process.stdin.on('data', chunk => chunks.push(chunk))
    process.stdin.on('end', () => resolve(chunks.join('')))
    process.stdin.on('error', reject)
  })
}

async function main() {
  const mode = process.argv[2]
  if (process.argv.length !== 3 || !MODES.includes(mode)) {
    fail('usage: cli.js merge|merge2|regions')
    return
  }

  const raw = await readStdin()
  const docs = splitInput(raw)
  if (!docs) {
    fail('expected three parts separated by %%%')
    return
  }

  const [mine, base, theirs] = docs
  const changesMine = computeChanges(base, mine, 'mine')
  const changesTheirs = computeChanges(base, theirs, 'theirs')
  const resolutions = buildRegions(base, mine, theirs, changesMine, changesTheirs)

  const output = mode === 'regions'
    ? formatRegions(resolutions)
    : formatMerge(resolutions, { includeBase: mode === 'merge' })

  await new Promise(resolve => process.stdout.write(output.text, resolve))
  process.exitCode = output.conflict ? 1 : 0
}

main().catch(err => {
  process.stderr.write(`error: ${err && err.message ? err.message : String(err)}\n`)
  process.exitCode = 2
})
"}

