export const NAME_RE = /^[A-Za-z0-9_.\/:-]+$/
const INT_RE = /^(0|[1-9][0-9]*)$/

export function isValidToken(s) {
  return NAME_RE.test(s)
}

// Parses an unsigned decimal integer with no leading zero (unless exactly
// "0") into a BigInt. Returns null when the string does not match.
export function parseUint(s) {
  if (!INT_RE.test(s)) return null
  return BigInt(s)
}
"}

{"file_path":"/tmp/claude-0/-home-user-deepseek-harness/f53f80cc-1f77-5d02-a862-99d59ffabdce/scratchpad/bench/runs/h4-craft-sonnet-t5/cell-4rD6jO/src/policies.js","content":"// Policy implementations. Each keeps one independent state per key.

export class TokenBucket {
  constructor(capacity, refill, per) {
    this.refill = refill
    this.per = per
    // Tokens are tracked scaled by `per` so that partial-period accrual
    // (refill * n / per) stays exact using BigInt arithmetic.
    this.scaledCapacity = capacity * per
    this.states = new Map()
  }

  advance(key, tick) {
    let st = this.states.get(key)
    if (!st) {
      // Starts full when a key first reaches it.
      this.states.set(key, { scaledTokens: this.scaledCapacity, lastTick: tick })
      return
    }
    const n = tick - st.lastTick
    if (n > 0n) {
      st.scaledTokens += this.refill * n
      if (st.scaledTokens > this.scaledCapacity) st.scaledTokens = this.scaledCapacity
    }
    st.lastTick = tick
  }

  canAllow(key) {
    const st = this.states.get(key)
    return st.scaledTokens >= this.per
  }

  record(key) {
    const st = this.states.get(key)
    st.scaledTokens -= this.per
  }
}

export class SlidingWindow {
  constructor(limit, span) {
    this.limit = limit
    this.span = span
    this.states = new Map()
  }

  advance(key, tick) {
    let arr = this.states.get(key)
    if (!arr) {
      arr = []
      this.states.set(key, arr)
    }
    const threshold = tick - this.span
    let idx = 0
    while (idx < arr.length && arr[idx] <= threshold) idx++
    if (idx > 0) arr.splice(0, idx)
  }

  canAllow(key) {
    const arr = this.states.get(key)
    return BigInt(arr.length) < this.limit
  }

  record(key, tick) {
    const arr = this.states.get(key)
    arr.push(tick)
  }
}
"}

