// Error whose message is "line N: <reason>".

import { isValidToken, parseUint } from './util.js'

const FIELD_MIN = {
  capacity: 1n,
  refill: 0n,
  per: 1n,
  limit: 0n,
  span: 1n,
  tick: 0n,
}

function parseField(str, field) {
  const v = parseUint(str)
  if (v === null || v < FIELD_MIN[field]) {
    throw new Error(`${field} must be an integer of at least ${FIELD_MIN[field]}`)
  }
  return v
}

export function parseProgram(text) {
  const lines = text.split('\n')
  if (lines.length > 0 && lines[lines.length - 1] === '') lines.pop()

  const policies = new Map()
  const routes = []
  const routePrefixes = new Set()
  const events = []
  let eventSeen = false
  let lastTick = null

  for (let i = 0; i < lines.length; i++) {
    const lineNo = i + 1
    const trimmed = lines[i].trim()
    if (trimmed === '' || trimmed.startsWith('#')) continue

    const tokens = trimmed.split(/\s+/)
    const kw = tokens[0]

