import { ScanError } from './errors.js'
import { scanNumber } from './numbers.js'
import { scanString, scanRawString } from './strings.js'

const KEYWORDS = new Set(['let', 'if', 'else', 'while', 'return', 'true', 'false', 'null'])
const TWO_CHAR_PUNCT = new Set(['==', '!=', '<=', '>=', '&&', '||', '->', '=>'])
const ONE_CHAR_PUNCT = new Set('+-*/%=<>!(){}[],;.')

function scanBlockComment(s) {
  const pos = s.pos()
  s.advance()
  s.advance() // /*
  let depth = 1
  while (depth > 0) {
    if (s.atEnd()) throw new ScanError(pos, 'unterminated block comment')
    const c = s.peek()
    if (c === '/' && s.peek(1) === '*') {
      s.advance()
      s.advance()
      depth++
    } else if (c === '*' && s.peek(1) === '/') {
      s.advance()
      s.advance()
      depth--
    } else {
      s.advance()
    }
  }
}

function skipTrivia(s) {
  while (true) {
    const c = s.peek()
    if (c === ' ' || c === '\t' || c === '\r' || c === '\n') {
      s.advance()
      continue
    }
    if (c === '/' && s.peek(1) === '/') {
      s.advance()
      s.advance()
      while (!s.atEnd() && s.peek() !== '\n') s.advance()
      continue
    }
    if (c === '/' && s.peek(1) === '*') {
      scanBlockComment(s)
      continue
    }
    break
  }
}

function scanIdent(s, pos) {
  let text = ''
  while (/[A-Za-z0-9_]/.test(s.peek())) text += s.advance()
  const kind = KEYWORDS.has(text) ? 'keyword' : 'ident'
  return { line: pos.line, col: pos.col, kind, text }
}

function scanPunct(s, pos) {
  const two = s.peek() + s.peek(1)
  if (TWO_CHAR_PUNCT.has(two)) {
    s.advance()
    s.advance()
    return { line: pos.line, col: pos.col, kind: 'punct', text: two }
  }
  const one = s.peek()
  if (ONE_CHAR_PUNCT.has(one)) {
    s.advance()
    return { line: pos.line, col: pos.col, kind: 'punct', text: one }
  }
  throw new ScanError(pos, `unexpected character ${one}`)
}

export function tokenize(text) {
  const s = new CharStream(text)
  const tokens = []
  while (true) {
    skipTrivia(s)
    if (s.atEnd()) break
    const pos = s.pos()
    const c = s.peek()
    if (c === '"') {
      tokens.push(scanString(s, pos))
    } else if (c === 'r' && s.peek(1) === '"') {
      tokens.push(scanRawString(s, pos))
    } else if (/[A-Za-z_]/.test(c)) {
      tokens.push(scanIdent(s, pos))
    } else if (c >= '0' && c <= '9') {
      tokens.push(scanNumber(s, pos))
    } else {
      tokens.push(scanPunct(s, pos))
    }
  }
  return tokens
}
"}

{"file_path":"src/cli.js","content":"#!/usr/bin/env node
/**
 * The command. `node src/cli.js tokens` prints every token of the source read
 * from standard input with its position, and `node src/cli.js stats` counts the
 * tokens by kind.
 */
import { tokenize } from './lexer.js'
import { ScanError } from './errors.js'

const STAT_KINDS = ['ident', 'keyword', 'number', 'punct', 'rawstring', 'string']

function readStdin() {
  return new Promise((resolve, reject) => {
    let data = ''
    process.stdin.setEncoding('utf8')
    process.stdin.on('data', chunk => {
      data += chunk
    })
    process.stdin.on('end', () => resolve(data))
    process.stdin.on('error', reject)
  })
}

function formatTokens(tokens) {
  return tokens.map(t => `${t.line}:${t.col} ${t.kind} ${t.text}\n`).join('')
}

function formatStats(tokens) {
  const counts = Object.fromEntries(STAT_KINDS.map(k => [k, 0]))
  for (const t of tokens) counts[t.kind]++
  const lines = STAT_KINDS.map(k => `${k} ${counts[k]}\n`)
  lines.push(`total ${tokens.length}\n`)
  return lines.join('')
}

async function main() {
  const mode = process.argv[2]
  if (process.argv.length !== 3 || (mode !== 'tokens' && mode !== 'stats')) {
    process.stderr.write('error: usage: cli.js tokens|stats\n')
    process.exitCode = 2
    return
  }

  const text = await readStdin()

  let tokens
  try {
    tokens = tokenize(text)
  } catch (err) {
    if (err instanceof ScanError) {
      process.stderr.write(`error: ${err.pos.line}:${err.pos.col}: ${err.message}\n`)
      process.exitCode = 2
      return
    }
    throw err
  }

  const out = mode === 'tokens' ? formatTokens(tokens) : formatStats(tokens)
  process.stdout.write(out)
  process.exitCode = 0
}

main().catch(err => {
  process.stderr.write(`error: ${err.message}\n`)
  process.exitCode = 2
})
"}

