{"file_path":"src/cycle.js","content":"/**
 * Depth-first cycle detection. Starts from each task in ascending name
 * order and walks each task's dependencies in ascending name order.
 * Returns the first cycle found, as an array of names running from the
 * re-entered task through the search stack back to itself, or null when
 * the graph is acyclic.
 */
export function findCycle(names, adjacency) {
  const state = new Map()
  const stack = []

  function visit(node) {
    state.set(node, 1)
    stack.push(node)
    const deps = [...(adjacency.get(node) || [])].sort()
    for (const dep of deps) {
      const st = state.get(dep) || 0
      if (st === 1) {
        const idx = stack.indexOf(dep)
        const cyclePath = stack.slice(idx)
        cyclePath.push(dep)
        return cyclePath
      } else if (st === 0) {
        const found = visit(dep)
        if (found) return found
      }
    }
    stack.pop()
    state.set(node, 2)
    return null
  }

  for (const name of names) {
    if ((state.get(name) || 0) === 0) {
      const found = visit(name)
      if (found) return found
    }
  }
  return null
}
"}

{"file_path":"src/parse.js","content":"import { CliError } from './errors.js'

const NAME_RE = /^[A-Za-z0-9_.-]+$/
const COST_RE = /^[0-9]+$/

/**
 * Parses the build graph from the raw text read from standard input.
 * Returns { tasks: Map<name, cost>, adjacency: Map<name, string[]> }.
 * Throws CliError for any malformed input.
 */
export function parseGraph(text) {
  const lines = text.split('\n')
  if (lines.length > 0 && lines[lines.length - 1] === '') lines.pop()

  const tasks = new Map()
  const adjacency = new Map()
  const usedNames = []

  for (let i = 0; i < lines.length; i++) {
    const lineNo = i + 1
    const trimmed = lines[i].trim()
    if (trimmed === '' || trimmed.startsWith('#')) continue

    const words = trimmed.split(/\s+/)
    const directive = words[0]

    if (directive === 'task') {
      if (words.length !== 3) {
        throw new CliError(`line ${lineNo}: expected task <name> <cost>`)
      }
      const [, name, costStr] = words
      if (!NAME_RE.test(name)) {
        throw new CliError(`line ${lineNo}: invalid task name ${name}`)
      }
      if (!COST_RE.test(costStr)) {
        throw new CliError(`line ${lineNo}: cost must be a non-negative integer`)
      }
      if (tasks.has(name)) {
        throw new CliError(`line ${lineNo}: task ${name} is declared twice`)
      }
      tasks.set(name, parseInt(costStr, 10))
      if (!adjacency.has(name)) adjacency.set(name, [])
    } else if (directive === 'dep') {
      if (words.length < 3) {
        throw new CliError(`line ${lineNo}: expected dep <name> <dependency>...`)
      }
      const name = words[1]
      const deps = words.slice(2)
      usedNames.push(name)
      if (!adjacency.has(name)) adjacency.set(name, [])
      const list = adjacency.get(name)
      for (const dep of deps) {
        usedNames.push(dep)
        if (!list.includes(dep)) list.push(dep)
      }
    } else {
      throw new CliError(`line ${lineNo}: unknown directive ${directive}`)
    }
  }

  for (const name of usedNames) {
    if (!tasks.has(name)) {
      throw new CliError(`unknown task ${name}`)
    }
  }

  return { tasks, adjacency }
}
"}

{"file_path":"src/schedule.js","content":"import { CycleError } from './errors.js'
import { findCycle } from './cycle.js'

/**
 * Computes start, finish and depth for every task given its dependency
 * graph. Throws CycleError when the graph is not a DAG.
 */
export function computeSchedule(names, tasks, adjacency) {
  const cycle = findCycle(names, adjacency)
  if (cycle) throw new CycleError(cycle)

  const memo = new Map()

  function compute(name) {
    if (memo.has(name)) return memo.get(name)
    const deps = adjacency.get(name) || []
    let start = 0
    let depth = 0
    for (const dep of deps) {
      const r = compute(dep)
      if (r.finish > start) start = r.finish
      if (r.depth + 1 > depth) depth = r.depth + 1
    }
    const finish = start + tasks.get(name)
    const result = { start, finish, depth }
    memo.set(name, result)
    return result
  }

  const results = new Map()
  let total = 0
  for (const name of names) {
    const r = compute(name)
    results.set(name, r)
    if (r.finish > total) total = r.finish
  }

  return { results, total }
}
"}

{"file_path":"src/pack.js","content":"/**
 * Simulates the build graph on a fixed number of workers, greedily
 * starting the ready task with the greatest priority whenever a worker
 * is free. Priority is the cost of the longest chain of dependents that
 * begins at a task, counting its own cost and continuing down to a task
 * that nothing depends on.
 */
function computePriorities(names, tasks, adjacency) {
  const dependents = new Map()
  for (const name of names) dependents.set(name, [])
  for (const [name, deps] of adjacency) {
    for (const dep of deps) {
      if (!dependents.has(dep)) dependents.set(dep, [])
      dependents.get(dep).push(name)
    }
  }

  const memo = new Map()
  function compute(name) {
    if (memo.has(name)) return memo.get(name)
    let maxDown = 0
    for (const dependent of dependents.get(name) || []) {
      const p = compute(dependent)
      if (p > maxDown) maxDown = p
    }
    const result = tasks.get(name) + maxDown
    memo.set(name, result)
    return result
  }

  const priorities = new Map()
  for (const name of names) priorities.set(name, compute(name))
  return priorities
}

export function computePack(names, tasks, adjacency, workerCount) {
  const priorities = computePriorities(names, tasks, adjacency)
  const finishOf = new Map()
  const scheduled = new Set()
  const workers = Array.from({ length: workerCount }, () => ({ busyUntil: 0, log: [] }))
  let currentInstant = 0
  const total = names.length

  while (scheduled.size < total) {
    for (;;) {
      let freeIdx = -1
      for (let i = 0; i < workers.length; i++) {
        if (workers[i].busyUntil <= currentInstant) {
          freeIdx = i
          break
        }
      }
      if (freeIdx === -1) break

      let best = null
      for (const name of names) {
        if (scheduled.has(name)) continue
        const deps = adjacency.get(name) || []
        let ready = true
        for (const dep of deps) {
          if (!finishOf.has(dep) || finishOf.get(dep) > currentInstant) {
            ready = false
            break
          }
        }
        if (!ready) continue
        const p = priorities.get(name)
        if (!best || p > best.p || (p === best.p && name < best.name)) {
          best = { name, p }
        }
      }
      if (!best) break

      const start = currentInstant
      const finish = start + tasks.get(best.name)
      finishOf.set(best.name, finish)
      scheduled.add(best.name)
      workers[freeIdx].busyUntil = finish
      workers[freeIdx].log.push({ name: best.name, start, finish })
    }

    if (scheduled.size >= total) break

    let next = Infinity
    for (const w of workers) {
      if (w.busyUntil > currentInstant && w.busyUntil < next) next = w.busyUntil
    }
    if (next === Infinity) break
    currentInstant = next
  }

  let makespan = 0
  for (const f of finishOf.values()) if (f > makespan) makespan = f

  return { workers, makespan }
}
"}

