{"file_path":"src/toposort.js","content":"/**
 * Iterative depth-first traversal shared by every mode. Starts from each
 * task in ascending name order and walks each task's dependencies in
 * ascending name order, exactly like a recursive DFS would, but with an
 * explicit stack so arbitrarily long chains cannot overflow the call
 * stack.
 *
 * Returns { cycle } when the graph is not a DAG: cycle runs from the
 * re-entered task through the search stack back to itself. Otherwise
 * returns { finishOrder }, a dependency-first topological order (every
 * task appears after all of its dependencies).
 */
export function traverse(names, adjacency) {
  const state = new Map() // 0/undefined = unvisited, 1 = in progress, 2 = done
  const finishOrder = []
  const pathStack = []

  for (const start of names) {
    if (state.get(start)) continue

    state.set(start, 1)
    pathStack.push(start)
    const frames = [{ node: start, deps: [...(adjacency.get(start) || [])].sort(), idx: 0 }]

    while (frames.length) {
      const frame = frames[frames.length - 1]
      if (frame.idx < frame.deps.length) {
        const dep = frame.deps[frame.idx++]
        const st = state.get(dep) || 0
        if (st === 1) {
          const cutIdx = pathStack.indexOf(dep)
          const cyclePath = pathStack.slice(cutIdx)
          cyclePath.push(dep)
          return { cycle: cyclePath }
        } else if (st === 0) {
          state.set(dep, 1)
          pathStack.push(dep)
          frames.push({ node: dep, deps: [...(adjacency.get(dep) || [])].sort(), idx: 0 })
        }
      } else {
        frames.pop()
        pathStack.pop()
        state.set(frame.node, 2)
        finishOrder.push(frame.node)
      }
    }
  }

  return { finishOrder }
}
"}

