/**
 * Returns the first cycle a depth-first search finds when it starts from
 * each task in ascending name order and walks each task's dependencies in
 * ascending name order, or null when the graph is acyclic.
 */
export function findCycle(names, adjacency) {
  const result = traverse(names, adjacency)
  return result.cycle || null
