{"file_path":"src/document.js","content":"/**
 * Line-level parsing: splits the document into directives, classifies each
 * line as blank/comment, header, or assignment, and builds the in-memory
 * table tree that json-output.js and keys-output.js walk.
 */

import { Cursor, parseDottedName, parseValue, pathToString, stepInto, assignInto } from './lexer.js'

function newTable() {
  return { type: 'table', map: new Map(), headerDefined: false }
}

function keyPath(segs) {
  return segs.map((name) => ({ kind: 'key', name }))
}

function processHeader(cur, state) {
  cur.pos++ // consume first [
  let isArray = false
  if (cur.peek() === '[') {
    isArray = true
    cur.pos++
  }
  cur.skipSpaces()
  const segs = parseDottedName(cur)
  cur.skipSpaces()
  if (isArray) {
    if (cur.line.slice(cur.pos, cur.pos + 2) === ']]') {
      cur.pos += 2
    } else {
      cur.err('unterminated table header')
    }
  } else {
    if (cur.peek() === ']') {
      cur.pos++
    } else {
      cur.err('unterminated table header')
    }
  }
  cur.skipSpaces()
  cur.checkComment()
  if (!cur.atEnd()) cur.err('trailing text after a table header')

  let table = state.root
  const path = []
  for (let i = 0; i < segs.length - 1; i++) {
    path.push({ kind: 'key', name: segs[i] })
    table = stepInto(table, segs[i], path, cur)
  }
  const last = segs[segs.length - 1]
  path.push({ kind: 'key', name: last })

  if (isArray) {
    let node = table.map.get(last)
    if (node === undefined) {
      node = { type: 'array-of-tables', tables: [] }
      table.map.set(last, node)
    } else if (node.type !== 'array-of-tables') {
      cur.err(`${pathToString(path)} is not an array of tables`)
    }
    const fresh = newTable()
    node.tables.push(fresh)
    state.current = fresh
    state.currentPath = path
  } else {
    let node = table.map.get(last)
    if (node === undefined) {
      node = newTable()
      table.map.set(last, node)
    } else if (node.type !== 'table') {
      cur.err(`${pathToString(path)} is not a table`)
    } else if (node.headerDefined) {
      cur.err(`table ${pathToString(path)} is defined twice`)
    }
    node.headerDefined = true
    state.current = node
    state.currentPath = path
  }
}

function processAssignment(cur, state) {
  const segs = parseDottedName(cur)
  cur.skipSpaces()
  cur.checkComment()
  if (cur.atEnd() || cur.peek() !== '=') cur.err('expected key = value')
  cur.pos++
  cur.skipSpaces()
  cur.checkComment()
  const valuePath = [...state.currentPath, ...keyPath(segs)]
  const value = parseValue(cur, valuePath)
  cur.skipSpaces()
  cur.checkComment()
  if (!cur.atEnd()) cur.err('trailing text after a value')
  assignInto(state.current, state.currentPath, segs, value, cur)
}

function processLine(lineText, lineNo, state) {
  let i = 0
  while (i < lineText.length && (lineText[i] === ' ' || lineText[i] === '\t')) i++
  if (i >= lineText.length) return
  const c0 = lineText[i]
  if (c0 === '#' || c0 === ';') return
  const cur = new Cursor(lineText, lineNo)
  cur.pos = i
  if (c0 === '[') {
    processHeader(cur, state)
  } else {
    processAssignment(cur, state)
  }
}

export function parseDocument(text) {
  const lines = text.split('\n')
  if (lines.length > 0 && lines[lines.length - 1] === '') lines.pop()
  const root = newTable()
  const state = { root, current: root, currentPath: [] }
  for (let i = 0; i < lines.length; i++) {
    processLine(lines[i], i + 1, state)
  }
  return root
}
"}

