{"file_path":"src/cli.js","content":"#!/usr/bin/env node
/**
 * The command. `node src/cli.js waves`, `node src/cli.js explain` and
 * `node src/cli.js pack <workers>` each report on the build graph read from
 * standard input.
 */
import { CliError } from './errors.js'
import { parseGraph } from './parse.js'
import { findCycle } from './cycle.js'
import { computeTimes } from './times.js'
import { pack } from './pack.js'

const USAGE = 'error: usage: cli.js waves|explain|pack <workers>'

function parseArgs(argv) {
  if (argv.length === 1 && (argv[0] === 'waves' || argv[0] === 'explain')) {
    return { mode: argv[0] }
  }
  if (argv.length === 2 && argv[0] === 'pack') {
    if (!/^[1-9][0-9]*$/.test(argv[1])) {
      throw new CliError('workers must be a positive integer')
    }
    return { mode: 'pack', workers: parseInt(argv[1], 10) }
  }
  throw new CliError(USAGE.slice('error: '.length))
}

function readStdin() {
  return new Promise((resolve, reject) => {
    let data = ''
    process.stdin.setEncoding('utf8')
    process.stdin.on('data', (chunk) => {
      data += chunk
    })
    process.stdin.on('end', () => resolve(data))
    process.stdin.on('error', reject)
  })
}

function formatWaves(tasks, times) {
  let maxDepth = -1
  for (const { depth } of times.values()) maxDepth = Math.max(maxDepth, depth)
  const lines = []
  for (let k = 0; k <= maxDepth; k++) {
    const names = [...tasks.keys()].filter((n) => times.get(n).depth === k).sort()
    lines.push(`wave ${k}: ${names.join(' ')}`)
  }
  let total = 0
  for (const { finish } of times.values()) total = Math.max(total, finish)
  lines.push(`total ${total}`)
  return lines.join('\n') + (lines.length ? '\n' : '')
}

function formatExplain(tasks, times) {
  const names = [...tasks.keys()].sort()
  const lines = names.map((n) => {
    const { start, finish, depth } = times.get(n)
    return `${n} start=${start} finish=${finish} depth=${depth}`
  })
  let total = 0
  for (const { finish } of times.values()) total = Math.max(total, finish)
  lines.push(`total ${total}`)
  return lines.join('\n') + '\n'
}

function formatPack(workers) {
  const lines = workers.map((w, i) => {
    const parts = w.log.map((t) => `${t.name}@${t.start}-${t.finish}`)
    return `worker ${i}:${parts.length ? ' ' + parts.join(' ') : ''}`
  })
  let makespan = 0
  for (const w of workers) for (const t of w.log) makespan = Math.max(makespan, t.finish)
  lines.push(`makespan ${makespan}`)
  return lines.join('\n') + '\n'
}

async function main() {
  const argv = process.argv.slice(2)
  const args = parseArgs(argv)

  const input = await readStdin()
  const { tasks, edges } = parseGraph(input)

  const cycle = findCycle(tasks, edges)
  if (cycle) {
    const err = new Error(`error: cycle: ${cycle.join(' -> ')}`)
    err.cycle = true
    throw err
  }

  let output
  if (args.mode === 'waves') {
    const times = computeTimes(tasks, edges)
    output = formatWaves(tasks, times)
  } else if (args.mode === 'explain') {
    const times = computeTimes(tasks, edges)
    output = formatExplain(tasks, times)
  } else {
    const workers = pack(tasks, edges, args.workers)
    output = formatPack(workers)
  }

  process.stdout.write(output, () => process.exit(0))
}

main().catch((err) => {
  if (err instanceof CliError) {
    process.stderr.write(`error: ${err.message}\n`, () => process.exit(err.code))
    return
  }
  if (err && err.cycle) {
    process.stderr.write(`${err.message}\n`, () => process.exit(3))
    return
  }
  process.stderr.write(`error: ${err && err.message ? err.message : String(err)}\n`, () => process.exit(2))
})
"}

