{"file_path":"src/comments.js","content":"import { err } from './errors.js'

export function skipLineComment(sc) {
  sc.advance() // /
  sc.advance() // /
  while (!sc.eof() && sc.peek() !== '\n') sc.advance()
}

export function skipBlockComment(sc) {
  const startPos = sc.pos()
  sc.advance() // /
  sc.advance() // *
  let depth = 1
  while (depth > 0) {
    if (sc.eof()) throw err(startPos, 'unterminated block comment')
    if (sc.peek() === '/' && sc.peek(1) === '*') {
      sc.advance()
      sc.advance()
      depth++
    } else if (sc.peek() === '*' && sc.peek(1) === '/') {
      sc.advance()
      sc.advance()
      depth--
    } else {
      sc.advance()
    }
  }
}
"}

{"file_path":"src/numbers.js","content":"import { err } from './errors.js'
import { isDigit, isHexDigit, isBinDigit, isOctDigit, isIdentChar } from './chars.js'

// Consumes a maximal run of digits (per isDigitFn) allowing a single
// underscore between two digits of the run, and nowhere else. Returns the
// consumed text and how many digits (not counting underscores) it held.
function consumeDigitRun(sc, isDigitFn) {
  let text = ''
  let count = 0
  if (!isDigitFn(sc.peek())) return { text, count }
  for (;;) {
    const c = sc.peek()
    if (isDigitFn(c)) {
      text += sc.advance()
      count++
    } else if (c === '_' && count > 0 && isDigitFn(sc.peek(1))) {
      text += sc.advance()
    } else {
      break
    }
  }
  return { text, count }
}

export function scanNumber(sc) {
  const startPos = sc.pos()
  let text = ''
  let ok

  const c0 = sc.peek()
  const c1 = sc.peek(1)
  if (c0 === '0' && (c1 === 'x' || c1 === 'X')) {
    text += sc.advance()
    text += sc.advance()
    const digits = consumeDigitRun(sc, isHexDigit)
    text += digits.text
    ok = digits.count > 0
  } else if (c0 === '0' && (c1 === 'b' || c1 === 'B')) {
    text += sc.advance()
    text += sc.advance()
    const digits = consumeDigitRun(sc, isBinDigit)
    text += digits.text
    ok = digits.count > 0
  } else if (c0 === '0' && (c1 === 'o' || c1 === 'O')) {
    text += sc.advance()
    text += sc.advance()
    const digits = consumeDigitRun(sc, isOctDigit)
    text += digits.text
    ok = digits.count > 0
  } else {
    const intDigits = consumeDigitRun(sc, isDigit)
    text += intDigits.text
    ok = true
    if (sc.peek() === '.' && isDigit(sc.peek(1))) {
      text += sc.advance()
      const fracDigits = consumeDigitRun(sc, isDigit)
      text += fracDigits.text
    }
    if (
      (sc.peek() === 'e' || sc.peek() === 'E') &&
      (isDigit(sc.peek(1)) || ((sc.peek(1) === '+' || sc.peek(1) === '-') && isDigit(sc.peek(2))))
    ) {
      text += sc.advance()
      if (sc.peek() === '+' || sc.peek() === '-') text += sc.advance()
      const expDigits = consumeDigitRun(sc, isDigit)
      text += expDigits.text
    }
  }

  let trailing = ''
  while (!sc.eof() && isIdentChar(sc.peek())) trailing += sc.advance()
  text += trailing

  if (!ok || trailing.length > 0) {
    throw err(startPos, 'invalid number ' + text)
  }
  return { kind: 'number', text, pos: startPos }
}
"}

{"file_path":"src/strings.js","content":"import { err } from './errors.js'
import { isHexDigit } from './chars.js'

export function scanString(sc) {
  const startPos = sc.pos()
  sc.advance() // opening "
  let value = ''
  for (;;) {
    if (sc.eof()) throw err(startPos, 'unterminated string')
    const cPos = sc.pos()
    const c = sc.peek()
    if (c === '"') {
      sc.advance()
      return { kind: 'string', text: JSON.stringify(value), pos: startPos }
    }
    if (c === '\n') throw err(cPos, 'newline in string')
    if (c === '\\') {
      const bsPos = cPos
      sc.advance() // backslash
      if (sc.eof()) throw err(startPos, 'unterminated string')
      const ec = sc.peek()
      if (ec === 'n') {
        value += '\n'
        sc.advance()
      } else if (ec === 't') {
        value += '\t'
        sc.advance()
      } else if (ec === 'r') {
        value += '\r'
        sc.advance()
      } else if (ec === '\\') {
        value += '\\'
        sc.advance()
      } else if (ec === '"') {
        value += '"'
        sc.advance()
      } else if (ec === '0') {
        value += '\0'
        sc.advance()
      } else if (ec === 'x') {
        sc.advance()
        const h1 = sc.peek()
        const h2 = sc.peek(1)
        if (h1 !== undefined && h2 !== undefined && isHexDigit(h1) && isHexDigit(h2)) {
          sc.advance()
          sc.advance()
          value += String.fromCharCode(parseInt(h1 + h2, 16))
        } else {
          throw err(bsPos, 'invalid escape \\x')
        }
      } else if (ec === 'u') {
        sc.advance()
        if (sc.peek() !== '{') throw err(bsPos, 'invalid escape \\u')
        sc.advance()
        let hex = ''
        while (!sc.eof() && isHexDigit(sc.peek())) hex += sc.advance()
        if (hex.length === 0 || sc.peek() !== '}') throw err(bsPos, 'invalid escape \\u')
        sc.advance() // }
        const cp = parseInt(hex, 16)
        if (cp > 0x10ffff) throw err(bsPos, 'invalid escape \\u')
        value += String.fromCodePoint(cp)
      } else {
        throw err(bsPos, 'invalid escape \\' + ec)
      }
    } else {
      value += sc.advance()
    }
  }
}

export function scanRawString(sc) {
  const startPos = sc.pos()
  sc.advance() // r
  sc.advance() // "
  let value = ''
  for (;;) {
    if (sc.eof()) throw err(startPos, 'unterminated string')
    const c = sc.peek()
    if (c === '"') {
      sc.advance()
      return { kind: 'rawstring', text: JSON.stringify(value), pos: startPos }
    }
    value += sc.advance()
  }
}
"}

{"file_path":"src/punct.js","content":"const TWO = new Set(['==', '!=', '<=', '>=', '&&', '||', '->', '=>'])
const ONE = new Set('+-*/%=<>!(){}[],;.'.split(''))

export function matchPunct(sc) {
  const c1 = sc.peek()
  const c2 = sc.peek(1)
  if (c1 !== undefined && c2 !== undefined && TWO.has(c1 + c2)) {
    sc.advance()
    sc.advance()
    return c1 + c2
  }
  if (c1 !== undefined && ONE.has(c1)) {
    sc.advance()
    return c1
  }
  return null
}
"}

{"file_path":"src/lexer.js","content":"import { Scanner } from './scanner.js'
import { err, LexError } from './errors.js'
import { isLetter, isDigit, isIdentChar } from './chars.js'
import { skipLineComment, skipBlockComment } from './comments.js'
import { scanNumber } from './numbers.js'
import { scanString, scanRawString } from './strings.js'
import { matchPunct } from './punct.js'

export { LexError }

const KEYWORDS = new Set(['let', 'if', 'else', 'while', 'return', 'true', 'false', 'null'])

function scanIdent(sc) {
  const pos = sc.pos()
  let text = ''
  while (!sc.eof() && isIdentChar(sc.peek())) text += sc.advance()
  const kind = KEYWORDS.has(text) ? 'keyword' : 'ident'
  return { kind, text, pos }
}

export function scan(source) {
  const sc = new Scanner(source)
  const tokens = []
  while (!sc.eof()) {
    const c = sc.peek()
    if (c === ' ' || c === '\t' || c === '\r' || c === '\n') {
      sc.advance()
      continue
    }
    if (c === '/' && sc.peek(1) === '/') {
      skipLineComment(sc)
      continue
    }
    if (c === '/' && sc.peek(1) === '*') {
      skipBlockComment(sc)
      continue
    }
    if (c === '"') {
      tokens.push(scanString(sc))
      continue
    }
    if (c === 'r' && sc.peek(1) === '"') {
      tokens.push(scanRawString(sc))
      continue
    }
    if (isLetter(c) || c === '_') {
      tokens.push(scanIdent(sc))
      continue
    }
    if (isDigit(c)) {
      tokens.push(scanNumber(sc))
      continue
    }
    const pos = sc.pos()
    const p = matchPunct(sc)
    if (p) {
      tokens.push({ kind: 'punct', text: p, pos })
      continue
    }
    throw err(pos, 'unexpected character ' + c)
  }
  return tokens
}
"}

{"file_path":"src/format.js","content":"const STAT_KINDS = ['ident', 'keyword', 'number', 'punct', 'rawstring', 'string']

export function formatTokens(tokens) {
  let out = ''
  for (const t of tokens) out += `${t.pos.line}:${t.pos.col} ${t.kind} ${t.text}\n`
  return out
}

export function formatStats(tokens) {
  const counts = Object.fromEntries(STAT_KINDS.map((k) => [k, 0]))
  for (const t of tokens) counts[t.kind]++
  let out = ''
  for (const k of STAT_KINDS) out += `${k} ${counts[k]}\n`
  out += `total ${tokens.length}\n`
  return out
}
"}

{"file_path":"src/cli.js","content":"#!/usr/bin/env node
/**
 * The command. `node src/cli.js tokens` prints every token of the source read
 * from standard input with its position, and `node src/cli.js stats` counts the
 * tokens by kind.
 */

import { scan, LexError } from './lexer.js'
import { formatTokens, formatStats } from './format.js'

function readStdin() {
  return new Promise((resolve, reject) => {
    let data = ''
    process.stdin.setEncoding('utf8')
    process.stdin.on('data', (chunk) => {
      data += chunk
    })
    process.stdin.on('end', () => resolve(data))
    process.stdin.on('error', reject)
  })
}

function usageError() {
  process.stderr.write('error: usage: cli.js tokens|stats\n')
  process.exitCode = 2
}

async function main() {
  const args = process.argv.slice(2)
  if (args.length !== 1 || (args[0] !== 'tokens' && args[0] !== 'stats')) {
    usageError()
    return
  }
  const mode = args[0]
  const text = await readStdin()

  let tokens
  try {
    tokens = scan(text)
  } catch (e) {
    if (e instanceof LexError) {
      process.stderr.write(`error: ${e.pos.line}:${e.pos.col}: ${e.reason}\n`)
      process.exitCode = 2
      return
    }
    throw e
  }

  const out = mode === 'tokens' ? formatTokens(tokens) : formatStats(tokens)
  process.stdout.write(out)
}

main().catch((e) => {
  process.stderr.write(`error: ${e && e.message ? e.message : String(e)}\n`)
  process.exitCode = 2
})
"}

