{"file_path":"src/cli.js","content":"#!/usr/bin/env node
/**
 * The command. `node src/cli.js rounds` prints every round of the instant-runoff
 * count read from standard input, and `node src/cli.js tally` prints only how
 * many rounds ran and who won.
 */

import fs from 'node:fs'
import { ParseError } from './errors.js'
import { parseElection } from './parse.js'
import { runElection } from './count.js'
import { formatRounds, formatTally } from './format.js'

function fail(message) {
  process.stderr.write(`error: ${message}\n`)
  process.exitCode = 2
}

function main() {
  const args = process.argv.slice(2)
  if (args.length !== 1 || (args[0] !== 'rounds' && args[0] !== 'tally')) {
    fail('usage: cli.js rounds|tally')
    return
  }
  const mode = args[0]

  const input = fs.readFileSync(0, 'utf8')

  let election
  try {
    election = parseElection(input)
  } catch (err) {
    if (err instanceof ParseError) {
      process.stderr.write(`${err.format()}\n`)
      process.exitCode = 2
      return
    }
    throw err
  }

  const result = runElection(election.candidates, election.ballots)
  const output = mode === 'rounds' ? formatRounds(result) : formatTally(result)
  process.stdout.write(output)
  process.exitCode = 0
}

main()
"}

