{"file_path":"src/errors.js","content":"/**
 * Small error type carrying the line number so cli.js can format
 * `error: line N: <reason>` in one place.
 */
export class LineError extends Error {
  constructor(line, reason) {
    super(reason)
    this.line = line
  }
}

