const TOKEN_RE = /^[A-Za-z0-9_./:-]+$/
const UINT_RE = /^(0|[1-9][0-9]*)$/

export function isValidToken(s) {
  return TOKEN_RE.test(s)
}

// Parses an unsigned decimal integer string into a BigInt, or returns
