 * the per-event verdict log and per-key/total summary counts.
 */

function findRoute(routes, key) {
  let best = null
  for (const route of routes) {
    if (key.startsWith(route.prefix)) {
      if (!best || route.prefix.length > best.prefix.length) best = route
    }
  }
  return best
}

export function simulate({ policies, routes, events }) {
  const log = [] // { tick, key, allow, denyPolicy }
  const perKey = new Map() // key -> { allowed, denied }
  let totalAllowed = 0n
  let totalDenied = 0n

  const bump = (key, allow) => {
    let s = perKey.get(key)
    if (!s) {
      s = { allowed: 0n, denied: 0n }
      perKey.set(key, s)
    }
    if (allow) s.allowed++
    else s.denied++
  }

  for (const { tick, key } of events) {
    const route = findRoute(routes, key)
    if (!route) {
      bump(key, true)
      totalAllowed++
      log.push({ tick, key, allow: true })
      continue
    }

    const routePolicies = route.policies.map((name) => policies.get(name))
    for (const p of routePolicies) p.advance(key, tick)

    let denyName = null
    for (const p of routePolicies) {
      if (!p.allows(key)) {
        if (denyName === null) denyName = p.name
      }
    }

    if (denyName === null) {
      for (const p of routePolicies) p.record(key, tick)
      bump(key, true)
      totalAllowed++
      log.push({ tick, key, allow: true })
    } else {
