import { colLetters, parseKey, compareAddresses } from './address.js'

function walk(node, set) {
  switch (node.type) {
    case 'ref':
      if (node.addr.valid) set.add(node.addr.upper)
      return
    case 'range': {
      const { from, to } = node
      if (!from.valid || !to.valid) return
      const c1 = Math.min(from.col, to.col)
      const c2 = Math.max(from.col, to.col)
      const r1 = Math.min(from.row, to.row)
      const r2 = Math.max(from.row, to.row)
      for (let c = c1; c <= c2; c++) {
        for (let r = r1; r <= r2; r++) set.add(colLetters(c) + r)
      }
      return
    }
    case 'unary':
      walk(node.expr, set)
      return
    case 'binop':
      walk(node.left, set)
      walk(node.right, set)
      return
    case 'call':
      for (const arg of node.args) walk(arg, set)
      return
    case 'num':
    case 'bool':
      return
    default:
      throw new Error('unknown node ' + node.type)
  }
}

// Returns the sorted list of distinct addresses a cell's content names
// directly (ranges expanded). A literal, or a formula the grammar does not
// accept, names none.
export function cellDeps(content) {
  if (content === '' || content[0] !== '=') return []
  const parsed = parseFormula(content.slice(1))
  if (!parsed.ok) return []
  const set = new Set()
  walk(parsed.ast, set)
  const keys = [...set]
  keys.sort((a, b) => compareAddresses(parseKey(a), parseKey(b)))
  return keys
}
"}

