{"file_path":"src/uri.js","content":"// URI reference parsing, normalization and resolution per RFC 3986.

export class UriError extends Error {}

const DEFAULT_PORTS = { http: '80', ws: '80', https: '443', wss: '443', ftp: '21' }

// Parse a URI reference into { scheme, authority, path, query, fragment }.
// Absent components are `undefined`; present-but-empty components are ''.
export function parseUri(s) {
  let rest = s
  let scheme

  let colonIdx = -1
  for (let i = 0; i < rest.length; i++) {
    const c = rest[i]
    if (c === ':') {
      colonIdx = i
      break
    }
    if (c === '/' || c === '?' || c === '#') break
  }
  if (colonIdx !== -1) {
    scheme = rest.slice(0, colonIdx)
    rest = rest.slice(colonIdx + 1)
  }

  let authority
  if (rest.startsWith('//')) {
    rest = rest.slice(2)
    let end = rest.length
    for (let i = 0; i < rest.length; i++) {
      const c = rest[i]
      if (c === '/' || c === '?' || c === '#') {
        end = i
        break
      }
    }
    authority = rest.slice(0, end)
    rest = rest.slice(end)
  }

  let pathEnd = rest.length
  for (let i = 0; i < rest.length; i++) {
    const c = rest[i]
    if (c === '?' || c === '#') {
      pathEnd = i
      break
    }
  }
  const path = rest.slice(0, pathEnd)
  rest = rest.slice(pathEnd)

  let query
  if (rest.startsWith('?')) {
    let qEnd = rest.length
    for (let i = 1; i < rest.length; i++) {
      if (rest[i] === '#') {
        qEnd = i
        break
      }
    }
    query = rest.slice(1, qEnd)
    rest = rest.slice(qEnd)
  }

  let fragment
  if (rest.startsWith('#')) {
    fragment = rest.slice(1)
  }

  return { scheme, authority, path, query, fragment }
}

// Split an authority string into { userinfo, host, port }.
export function parseAuthority(a) {
  let userinfo
  let hostport = a
  const at = a.lastIndexOf('@')
  if (at !== -1) {
    userinfo = a.slice(0, at)
    hostport = a.slice(at + 1)
  }
  const bracket = hostport.lastIndexOf(']')
  const searchFrom = bracket + 1
  const colon = hostport.indexOf(':', searchFrom)
  let host
  let port
  if (colon !== -1) {
    host = hostport.slice(0, colon)
    port = hostport.slice(colon + 1)
  } else {
    host = hostport
    port = undefined
  }
  return { userinfo, host, port }
}

function isHexDigit(c) {
  return (c >= '0' && c <= '9') || (c >= 'a' && c <= 'f') || (c >= 'A' && c <= 'F')
}

function isUnreserved(ch) {
  return (
    (ch >= 'A' && ch <= 'Z') ||
    (ch >= 'a' && ch <= 'z') ||
    (ch >= '0' && ch <= '9') ||
    ch === '-' ||
    ch === '.' ||
    ch === '_' ||
    ch === '~'
  )
}

// Uppercase %XX triplets and decode the ones that stand for unreserved chars.
export function normalizePercent(str, componentName) {
  let out = ''
  for (let i = 0; i < str.length; i++) {
    if (str[i] === '%') {
      const h1 = str[i + 1]
      const h2 = str[i + 2]
      if (h1 === undefined || h2 === undefined || !isHexDigit(h1) || !isHexDigit(h2)) {
        throw new UriError(`the ${componentName} has a truncated percent-encoding`)
      }
      const upper = (h1 + h2).toUpperCase()
      const code = parseInt(upper, 16)
      const ch = String.fromCharCode(code)
      if (isUnreserved(ch)) {
        out += ch
      } else {
        out += '%' + upper
      }
      i += 2
    } else {
      out += str[i]
    }
  }
  return out
}

// Remove dot segments from a path per RFC 3986 section 5.2.4.
export function removeDotSegments(path) {
  let input = path
  let output = ''
  while (input.length) {
    if (input.startsWith('../')) {
      input = input.slice(3)
    } else if (input.startsWith('./')) {
      input = input.slice(2)
    } else if (input.startsWith('/./')) {
      input = '/' + input.slice(3)
    } else if (input === '/.') {
      input = '/'
    } else if (input.startsWith('/../')) {
      input = '/' + input.slice(4)
      const idx = output.lastIndexOf('/')
      output = idx === -1 ? '' : output.slice(0, idx)
    } else if (input === '/..') {
      input = '/'
      const idx = output.lastIndexOf('/')
      output = idx === -1 ? '' : output.slice(0, idx)
    } else if (input === '.' || input === '..') {
      input = ''
    } else {
      let idx = input[0] === '/' ? 1 : 0
      let nextSlash = input.indexOf('/', idx)
      if (nextSlash === -1) nextSlash = input.length
      output += input.slice(0, nextSlash)
      input = input.slice(nextSlash)
    }
  }
  return output
}

function serialize({ scheme, authority, path, query, fragment }) {
  let out = ''
  if (scheme !== undefined) out += scheme + ':'
  if (authority !== undefined) out += '//' + authority
  out += path
  if (query !== undefined) out += '?' + query
  if (fragment !== undefined) out += '#' + fragment
  return out
}

// Normalize a parsed URI reference and return its string form.
export function normalizeParsed(parsed) {
  let { scheme, authority, path, query, fragment } = parsed

  if (scheme !== undefined) scheme = scheme.toLowerCase()

  let userinfo
  let host
  let port
  if (authority !== undefined) {
    const a = parseAuthority(authority)
    userinfo = a.userinfo
    host = a.host
    port = a.port
  }

  if (userinfo !== undefined) userinfo = normalizePercent(userinfo, 'userinfo')
  if (host !== undefined) host = normalizePercent(host, 'host')
  path = normalizePercent(path, 'path')
  if (query !== undefined) query = normalizePercent(query, 'query')
  if (fragment !== undefined) fragment = normalizePercent(fragment, 'fragment')

  if (host !== undefined) host = host.toLowerCase()

  if (port !== undefined) {
    const isDefault = scheme !== undefined && DEFAULT_PORTS[scheme] === port
    if (port === '' || isDefault) port = undefined
  }

  path = removeDotSegments(path)

  if (authority !== undefined && path === '') path = '/'

  let authorityOut
  if (authority !== undefined) {
    authorityOut = ''
    if (userinfo !== undefined) authorityOut += userinfo + '@'
    authorityOut += host
    if (port !== undefined) authorityOut += ':' + port
  }

  return serialize({ scheme, authority: authorityOut, path, query, fragment })
}

export function normalize(uriRef) {
  return normalizeParsed(parseUri(uriRef))
}

function mergePaths(base, refPath) {
  if (base.authority !== undefined && base.path === '') {
    return '/' + refPath
  }
  const idx = base.path.lastIndexOf('/')
  if (idx === -1) return refPath
  return base.path.slice(0, idx + 1) + refPath
}

// Resolve a reference against a base per RFC 3986 section 5.2.2 (strict),
// returning the normalized result.
export function resolve(baseStr, refStr) {
  const base = parseUri(baseStr)
  if (base.scheme === undefined) {
    throw new UriError('the base has no scheme')
  }
  const ref = parseUri(refStr)
  let target

  if (ref.scheme !== undefined) {
    target = { scheme: ref.scheme, authority: ref.authority, path: ref.path, query: ref.query, fragment: ref.fragment }
  } else if (ref.authority !== undefined) {
    target = { scheme: base.scheme, authority: ref.authority, path: ref.path, query: ref.query, fragment: ref.fragment }
  } else if (ref.path === '') {
    target = {
      scheme: base.scheme,
      authority: base.authority,
      path: base.path,
      query: ref.query !== undefined ? ref.query : base.query,
      fragment: ref.fragment,
    }
  } else {
    const path = ref.path.startsWith('/') ? ref.path : mergePaths(base, ref.path)
    target = { scheme: base.scheme, authority: base.authority, path, query: ref.query, fragment: ref.fragment }
  }

  return normalizeParsed(target)
}
"}

