{"file_path":"src/cli.js","content":"#!/usr/bin/env node
/**
 * The command. `node src/cli.js normalize` normalizes one URI reference per
 * input line; `node src/cli.js resolve` resolves the reference on each line
 * against the base that precedes it. Both print one result per line.
 */

import { normalize, resolve, UriError } from './uri.js'

function splitRecords(input) {
  if (input === '') return []
  const lines = input.split('\n')
  if (lines[lines.length - 1] === '') lines.pop()
  return lines
}

function readStdin() {
  return new Promise((resolvePromise, reject) => {
    const chunks = []
    process.stdin.setEncoding('utf8')
    process.stdin.on('data', (chunk) => chunks.push(chunk))
    process.stdin.on('end', () => resolvePromise(chunks.join('')))
    process.stdin.on('error', reject)
  })
}

function fail(message) {
  process.stderr.write(`error: ${message}\n`, () => {
    process.exitCode = 2
  })
}

async function main() {
  const args = process.argv.slice(2)
  if (args.length !== 1 || (args[0] !== 'normalize' && args[0] !== 'resolve')) {
    fail('usage: cli.js normalize|resolve')
    return
  }
  const mode = args[0]

  const input = await readStdin()
  const records = splitRecords(input)
  const results = []

  for (let i = 0; i < records.length; i++) {
    const lineNum = i + 1
    const record = records[i]
    try {
      if (mode === 'normalize') {
        results.push(normalize(record))
      } else {
        const spaceIdx = record.indexOf(' ')
        if (spaceIdx === -1) {
          throw new UriError('expected a base and a reference')
        }
        const base = record.slice(0, spaceIdx)
        const ref = record.slice(spaceIdx + 1)
        results.push(resolve(base, ref))
      }
    } catch (err) {
      if (err instanceof UriError) {
        fail(`line ${lineNum}: ${err.message}`)
        return
      }
      throw err
    }
  }

  const out = results.length ? results.join('\n') + '\n' : ''
  process.stdout.write(out)
}

main().catch((err) => {
  process.stderr.write(`error: ${err && err.message ? err.message : String(err)}\n`)
  process.exitCode = 1
})
"}

