import { parseQuotedString, parseDottedName } from './names.js'

const BOOL_RE = /^(true|false)$/
const INT_RE = /^[+-]?\d+(_\d+)*$/
const FLOAT_RE = /^[+-]?\d+(_\d+)*(?:(\.\d+(_\d+)*)(?:[eE][+-]?\d+(_\d+)*)?|[eE][+-]?\d+(_\d+)*)$/

function readBareValueToken(cursor) {
  const start = cursor.i
  while (!cursor.eof()) {
    const c = cursor.peek()
    if (c === ' ' || c === '\t' || c === ',' || c === ']' || c === '}') break
    cursor.i++
  }
  return cursor.s.slice(start, cursor.i)
}

function interpretBareToken(token) {
  if (BOOL_RE.test(token)) return { type: 'boolean', value: token === 'true' }
  if (INT_RE.test(token)) return { type: 'integer', value: Number(token.replace(/_/g, '')) }
  if (FLOAT_RE.test(token)) return { type: 'float', value: Number(token.replace(/_/g, '')) }
  throw new DocError(`invalid value ${token}`)
}

function atValueStop(cursor) {
  const c = cursor.peek()
  return c === undefined || c === ',' || c === ']' || c === '}' || c === '#' || c === ';'
}

/** Parses a value AST node: booleans, numbers, strings, arrays, and inline tables. */
export function parseValue(cursor) {
  cursor.skipWS()
  if (atValueStop(cursor)) throw new DocError('expected a value')
  const c = cursor.peek()
  if (c === '"' || c === "'") return { type: 'string', value: parseQuotedString(cursor) }
  if (c === '[') return parseArrayValue(cursor)
  if (c === '{') return parseInlineTableValue(cursor)
  const token = readBareValueToken(cursor)
  return interpretBareToken(token)
}

function parseArrayValue(cursor) {
  cursor.i++ // consume '['
  const items = []
  cursor.skipWS()
  if (cursor.peek() === ']') {
    cursor.i++
    return { type: 'array', items }
  }
  for (;;) {
    items.push(parseValue(cursor))
    cursor.skipWS()
    const c = cursor.peek()
    if (c === ',') {
      cursor.i++
      cursor.skipWS()
      if (cursor.peek() === ']') {
        cursor.i++
        return { type: 'array', items }
      }
      continue
    }
    if (c === ']') {
      cursor.i++
      return { type: 'array', items }
    }
    throw new DocError('unterminated array')
  }
}

function parseInlineTableValue(cursor) {
  cursor.i++ // consume '{'
  const pairs = []
  cursor.skipWS()
  if (cursor.peek() === '}') {
    cursor.i++
    return { type: 'inline-table', pairs }
  }
  for (;;) {
    const names = parseDottedName(cursor)
    cursor.skipWS()
    if (cursor.peek() !== '=') throw new DocError('expected = in an inline table')
    cursor.i++
    cursor.skipWS()
    const value = parseValue(cursor)
    pairs.push({ names, value })
    cursor.skipWS()
    const c = cursor.peek()
    if (c === ',') {
      cursor.i++
      cursor.skipWS()
      continue
    }
    if (c === '}') {
      cursor.i++
      return { type: 'inline-table', pairs }
    }
    throw new DocError('unterminated inline table')
  }
}
