export function pathAppendKey(path, name) {
  return path === '' ? name : `${path}.${name}`
}

export function pathAppendIndex(path, idx) {
  return `${path}[${idx}]`
}

function newTable(path, openedBySingleHeader) {
  return { kind: 'table', entries: new Map(), order: [], openedBySingleHeader, path }
}

/** Walks one intermediate path segment from `node`, creating a table if absent. */
function walkIntermediate(node, path, name) {
  const nextPath = pathAppendKey(path, name)
  const existing = node.entries.get(name)
  if (existing === undefined) {
    const t = newTable(nextPath, false)
    node.entries.set(name, t)
    node.order.push(name)
    return t
  }
  if (existing.kind === 'table') return existing
  if (existing.kind === 'array-of-tables') return existing.items[existing.items.length - 1]
  throw new DocError(`${nextPath} is not a table`)
}

/** Converts a value AST node into a tree node, resolving nested dotted keys against `path`. */
function convertValue(ast, path) {
  switch (ast.type) {
    case 'boolean':
    case 'integer':
    case 'float':
    case 'string':
      return { kind: ast.type, value: ast.value }
    case 'array':
      return { kind: 'array', items: ast.items.map((it, idx) => convertValue(it, pathAppendIndex(path, idx))) }
    case 'inline-table': {
      const t = newTable(path, false)
      for (const pair of ast.pairs) assignDotted(t, path, pair.names, pair.value)
      return t
    }
    default:
      throw new Error(`unknown value type ${ast.type}`)
  }
}

/** Assigns `value` at `names` (a dotted path) inside `table`, creating intermediate tables. */
export function assignDotted(table, tablePath, names, valueAst) {
  let cur = table
  let curPath = tablePath
  for (let i = 0; i < names.length - 1; i++) {
    cur = walkIntermediate(cur, curPath, names[i])
    curPath = cur.path
  }
  const lastName = names[names.length - 1]
  const finalPath = pathAppendKey(curPath, lastName)
  if (cur.entries.has(lastName)) throw new DocError(`key ${finalPath} is defined twice`)
  const node = convertValue(valueAst, finalPath)
  cur.entries.set(lastName, node)
  cur.order.push(lastName)
