export function handleHeader(root, double, names) {
  let cur = root
  let curPath = ''
  for (let i = 0; i < names.length - 1; i++) {
    cur = walkIntermediate(cur, curPath, names[i])
    curPath = cur.path
  }
  const lastName = names[names.length - 1]
  const finalPath = pathAppendKey(curPath, lastName)
  const existing = cur.entries.get(lastName)

  if (!double) {
    if (existing === undefined) {
      const t = newTable(finalPath, true)
      cur.entries.set(lastName, t)
      cur.order.push(lastName)
      return t
    }
    if (existing.kind === 'table') {
