/** Parses a whole configuration document into a root table node, or throws with a `line N: ` prefix. */
export function parseDocument(text) {
  const lines = text.split('\n')
  if (lines.length > 0 && lines[lines.length - 1] === '') lines.pop()

  const root = newRoot()
  let current = root

  for (let idx = 0; idx < lines.length; idx++) {
    const lineNo = idx + 1
    try {
      const directive = parseLine(lines[idx])
      if (directive.kind === 'skip') continue
      if (directive.kind === 'header') {
        current = handleHeader(root, directive.double, directive.names)
      } else {
        assignDotted(current, current.path, directive.names, directive.value)
      }
    } catch (e) {
      const reason = e && e.reason !== undefined ? e.reason : e.message
      const err = new Error(`line ${lineNo}: ${reason}`)
      throw err
    }
  }

  return root
}
