{"file_path":"src/parse.js","content":"/**
 * Parses a URI reference into its five generic components per RFC 3986.
 * Absent components are `undefined`; a present-but-empty component is `''`.
 * `path` is always a string (possibly empty), the other four may be absent.
 */
export function parseURI(s) {
  let rest = s

  let scheme
  for (let i = 0; i < rest.length; i++) {
    const c = rest[i]
    if (c === ':') {
      scheme = rest.slice(0, i)
      rest = rest.slice(i + 1)
      break
    }
    if (c === '/' || c === '?' || c === '#') break
  }

  let authority
  if (rest.startsWith('//')) {
    let end = rest.length
    for (let j = 2; j < rest.length; j++) {
      const c = rest[j]
      if (c === '/' || c === '?' || c === '#') { end = j; break }
    }
    authority = rest.slice(2, end)
    rest = rest.slice(end)
  }

  let pEnd = rest.length
  for (let j = 0; j < rest.length; j++) {
    if (rest[j] === '?' || rest[j] === '#') { pEnd = j; break }
  }
  const path = rest.slice(0, pEnd)
  let remainder = rest.slice(pEnd)

  let query
  if (remainder.startsWith('?')) {
    const hIdx = remainder.indexOf('#')
    if (hIdx === -1) {
      query = remainder.slice(1)
      remainder = ''
    } else {
      query = remainder.slice(1, hIdx)
      remainder = remainder.slice(hIdx)
    }
  }

  let fragment
  if (remainder.startsWith('#')) {
    fragment = remainder.slice(1)
  }

  return { scheme, authority, path, query, fragment }
}

/**
 * Splits an authority string into userinfo, host and port following the
 * task's rules: userinfo is everything before the last '@', the port is
 * everything after the first ':' that follows the last ']', and the host is
 * what lies between. userinfo and port may be `undefined`; host is always a
 * string.
 */
export function splitAuthority(authority) {
  let userinfo
  let hostport = authority
  const lastAt = authority.lastIndexOf('@')
  if (lastAt !== -1) {
    userinfo = authority.slice(0, lastAt)
    hostport = authority.slice(lastAt + 1)
  }

  const lastBracket = hostport.lastIndexOf(']')
  const searchFrom = lastBracket + 1
  const colonIdx = hostport.indexOf(':', searchFrom)

  let host = hostport
  let port
  if (colonIdx !== -1) {
    host = hostport.slice(0, colonIdx)
    port = hostport.slice(colonIdx + 1)
  }

  return { userinfo, host, port }
