{"file_path":"src/percent.js","content":"const UNRESERVED = /[A-Za-z0-9\-._~]/
const HEX = /^[0-9A-Fa-f]{2}$/

/**
 * Normalizes percent-encoded triplets in a single component: uppercases the
 * two hex digits, then replaces the triplet with the character it encodes
 * when that character is unreserved. Throws with the message
 * "the <name> has a truncated percent-encoding" when a '%' is not followed
 * by two hex digits.
 */
export function normalizePercentEncoding(str, name) {
  let result = ''
  for (let i = 0; i < str.length; i++) {
    const c = str[i]
    if (c === '%') {
      const hex = str.slice(i + 1, i + 3)
      if (!HEX.test(hex)) {
        throw new Error(`the ${name} has a truncated percent-encoding`)
      }
      const upper = hex.toUpperCase()
      const ch = String.fromCharCode(parseInt(upper, 16))
      result += UNRESERVED.test(ch) ? ch : '%' + upper
      i += 2
    } else {
      result += c
    }
  }
  return result
}
"}

{"file_path":"src/dotsegments.js","content":"/**
 * Removes dot segments from a path per RFC 3986 section 5.2.4.
 */
export function removeDotSegments(path) {
  let input = path
  let output = ''

  while (input.length > 0) {
    if (input.startsWith('../')) {
      input = input.slice(3)
    } else if (input.startsWith('./')) {
      input = input.slice(2)
    } else if (input.startsWith('/./')) {
      input = '/' + input.slice(3)
    } else if (input === '/.') {
      input = '/'
    } else if (input.startsWith('/../')) {
      input = '/' + input.slice(4)
      output = removeLastSegment(output)
    } else if (input === '/..') {
      input = '/'
      output = removeLastSegment(output)
    } else if (input === '.' || input === '..') {
      input = ''
    } else {
      let idx = input[0] === '/' ? 1 : 0
      let nextSlash = input.indexOf('/', idx)
      if (nextSlash === -1) nextSlash = input.length
      output += input.slice(0, nextSlash)
      input = input.slice(nextSlash)
    }
  }

  return output
}

function removeLastSegment(output) {
  const idx = output.lastIndexOf('/')
  return idx === -1 ? '' : output.slice(0, idx)
}
