{"file_path":"src/normalize.js","content":"import { splitAuthority } from './parse.js'
import { normalizePercentEncoding } from './percent.js'
import { removeDotSegments } from './dotsegments.js'

const DEFAULT_PORTS = { http: '80', ws: '80', https: '443', wss: '443', ftp: '21' }

function asciiLowercase(s) {
  return s.replace(/[A-Z]/g, (c) => c.toLowerCase())
}

/**
 * Normalizes a parsed URI reference: lowercases the scheme, normalizes
 * percent-encoding in every component (validating truncated ones in the
 * order path, userinfo, host, query, fragment), lowercases the host, drops a
 * default or empty port, removes dot segments from the path, and forces an
 * empty path to '/' when an authority is present.
 */
export function normalizeComponents(parsed) {
  const scheme = parsed.scheme !== undefined ? asciiLowercase(parsed.scheme) : undefined

  let userinfo
  let host
  let port
  if (parsed.authority !== undefined) {
    ;({ userinfo, host, port } = splitAuthority(parsed.authority))
  }

  const path = normalizePercentEncoding(parsed.path, 'path')
  if (userinfo !== undefined) userinfo = normalizePercentEncoding(userinfo, 'userinfo')
  if (host !== undefined) host = normalizePercentEncoding(host, 'host')
  const query = parsed.query !== undefined ? normalizePercentEncoding(parsed.query, 'query') : undefined
  const fragment = parsed.fragment !== undefined ? normalizePercentEncoding(parsed.fragment, 'fragment') : undefined

  if (host !== undefined) host = asciiLowercase(host)

  if (port !== undefined) {
    const defaultPort = scheme !== undefined ? DEFAULT_PORTS[scheme] : undefined
    if (port === '' || port === defaultPort) port = undefined
  }

  let authority
  if (parsed.authority !== undefined) {
    authority = (userinfo !== undefined ? userinfo + '@' : '') + host + (port !== undefined ? ':' + port : '')
  }

  let newPath = removeDotSegments(path)
  if (authority !== undefined && newPath === '') newPath = '/'

  return { scheme, authority, path: newPath, query, fragment }
}

/**
 * Renders parsed components back into a URI reference string.
 */
export function serialize(c) {
  let result = ''
  if (c.scheme !== undefined) result += c.scheme + ':'
  if (c.authority !== undefined) result += '//' + c.authority
  result += c.path
  if (c.query !== undefined) result += '?' + c.query
  if (c.fragment !== undefined) result += '#' + c.fragment
  return result
}
"}

{"file_path":"src/resolve.js","content":"import { removeDotSegments } from './dotsegments.js'

/**
 * Resolves a reference against a base per RFC 3986 section 5.2.2, strict
 * (a reference that repeats the base's scheme is still absolute). Returns
 * unnormalized components; the caller normalizes the result.
 */
export function resolveReference(base, ref) {
  const target = {}

  if (ref.scheme !== undefined) {
    target.scheme = ref.scheme
    target.authority = ref.authority
    target.path = removeDotSegments(ref.path)
    target.query = ref.query
  } else if (ref.authority !== undefined) {
    target.scheme = base.scheme
    target.authority = ref.authority
    target.path = removeDotSegments(ref.path)
    target.query = ref.query
  } else if (ref.path === '') {
    target.scheme = base.scheme
    target.authority = base.authority
    target.path = base.path
    target.query = ref.query !== undefined ? ref.query : base.query
  } else {
    target.scheme = base.scheme
    target.authority = base.authority
    target.path = ref.path.startsWith('/')
      ? removeDotSegments(ref.path)
      : removeDotSegments(mergePaths(base, ref.path))
    target.query = ref.query
  }

  target.fragment = ref.fragment
  return target
}

