{"file_path":"src/process-line.js","content":"import { parseURI } from './parse.js'
import { normalizeComponents, serialize } from './normalize.js'
import { resolveReference } from './resolve.js'
import { LineError } from './errors.js'

/**
 * Processes one record for the given mode and returns its output line.
 * Throws LineError (already carrying the line number) on failure.
 */
export function processLine(mode, line, lineNum) {
  try {
    if (mode === 'normalize') {
      return serialize(normalizeComponents(parseURI(line)))
    }

    const spaceIdx = line.indexOf(' ')
    if (spaceIdx === -1) {
      throw new Error('expected a base and a reference')
    }
    const baseStr = line.slice(0, spaceIdx)
    const refStr = line.slice(spaceIdx + 1)

    const base = parseURI(baseStr)
    if (base.scheme === undefined) {
      throw new Error('the base has no scheme')
    }
    const ref = parseURI(refStr)
    const target = resolveReference(base, ref)
    return serialize(normalizeComponents(target))
  } catch (err) {
    if (err instanceof LineError) throw err
    throw new LineError(lineNum, err.message)
  }
}
"}

{"file_path":"src/cli.js","content":"#!/usr/bin/env node
/**
 * The command. `node src/cli.js normalize` normalizes one URI reference per
 * input line; `node src/cli.js resolve` resolves the reference on each line
 * against the base that precedes it. Both print one result per line.
 */
import { processLine } from './process-line.js'
import { LineError } from './errors.js'

function splitRecords(input) {
  const lines = input.split('\n')
  if (lines[lines.length - 1] === '') lines.pop()
  return lines
}

function main() {
  const args = process.argv.slice(2)
  if (args.length !== 1 || (args[0] !== 'normalize' && args[0] !== 'resolve')) {
    process.stderr.write('error: usage: cli.js normalize|resolve\n')
    process.exitCode = 2
    return
  }
  const mode = args[0]

  let input = ''
  process.stdin.setEncoding('utf8')
  process.stdin.on('data', (chunk) => { input += chunk })
  process.stdin.on('end', () => {
    try {
      const records = splitRecords(input)
      const results = records.map((line, i) => processLine(mode, line, i + 1))
      const out = results.length ? results.join('\n') + '\n' : ''
      process.stdout.write(out, () => { process.exitCode = 0 })
    } catch (err) {
      if (err instanceof LineError) {
        process.stderr.write(`error: line ${err.lineNum}: ${err.message}\n`)
        process.exitCode = 2
      } else {
        throw err
      }
    }
  })
}

main()
"}

